$pass=0;$fail=0;function p7($ok,$name){global$pass,$fail;echo($ok?'PASS':'FAIL').": $name\n";$ok?$pass++:$fail++;}
$users=array_map(fn($r)=>(int)$r['id'],$conn->query("SELECT id FROM users WHERE status='active' ORDER BY id LIMIT 2")->fetch_all(MYSQLI_ASSOC));$resources=array_map(fn($r)=>(int)$r['resource_id'],$conn->query("SELECT resource_id FROM resources WHERE status='available' AND deleted_at IS NULL ORDER BY resource_id LIMIT 2")->fetch_all(MYSQLI_ASSOC));if(count($users)<2||count($resources)<2)exit(2);
[$owner,$other]=$users;[$resource1,$resource2]=$resources;$service=new ReservationService($conn);$reservationId=$requestId=$proposalId=$blockerId=0;$proposalIds=[];$notificationFloor=(int)$conn->query('SELECT COALESCE(MAX(notification_id),0) id FROM notifications')->fetch_assoc()['id'];$auditFloor=(int)$conn->query('SELECT COALESCE(MAX(log_id),0) id FROM audit_log')->fetch_assoc()['id'];
try{
