 $type='church_venue';$date='2097-01-11';$time='14:15:00';$start='2097-01-11 14:15:00';$end='2097-01-11 14:45:00';$status='pending';$details='Temporary conflict';$stmt=$conn->prepare('INSERT INTO reservations (user_id,reservation_type,event_date,event_time,start_at,end_at,service_duration_minutes,event_details,status) VALUES (?,?,?,?,?,?,30,?,?)');$stmt->bind_param('isssssss',$other,$type,$date,$time,$start,$end,$details,$status);$stmt->execute();$blockerId=$stmt->insert_id;$stmt->close();$stmt=$conn->prepare('INSERT INTO reservation_resources (reservation_id,resource_id) VALUES (?,?)');$stmt->bind_param('ii',$blockerId,$resource1);$stmt->execute();$stmt->close();
 $becameUnavailable=false;try{$service->respondToProposal($proposalId,$owner,true);}catch(DomainException$e){$becameUnavailable=true;}p7($becameUnavailable,'acceptance rechecks resources that became unavailable');$conn->query("UPDATE reservations SET status='cancelled' WHERE reservation_id=$blockerId");
 $service->respondToProposal($proposalId,$owner,true);$row=$conn->query("SELECT start_at,end_at FROM reservations WHERE reservation_id=$reservationId")->fetch_assoc();p7($row['start_at']==='2097-01-11 14:00:00'&&$row['end_at']==='2097-01-11 15:30:00','accepted proposal transactionally reschedules the reservation');
