 $event=$conn->query("SELECT event_date,start_time,status FROM schedule_events WHERE source_type='reservation' AND source_id=$reservationId")->fetch_assoc();p7($event['event_date']==='2097-01-11'&&$event['start_time']==='14:00:00'&&$event['status']==='active','reschedule updates the existing calendar event');
 $oldReminders=(int)$conn->query("SELECT COUNT(*) c FROM reservation_notifications WHERE reservation_id=$reservationId AND scheduled_for IN ('2097-01-09 10:00:00','2097-01-10 08:00:00') AND sent_at IS NULL")->fetch_assoc()['c'];p7($oldReminders===0,'rescheduling removes obsolete unsent reminders');
 $rejectId=$service->proposeSchedule($reservationId,['start_at'=>'2097-01-12 14:00:00','service_duration_minutes'=>90,'resource_ids'=>[$resource1]],$owner,'Second alternative schedule');$proposalIds[]=$rejectId;$service->respondToProposal($rejectId,$owner,false);$rejected=$conn->query("SELECT status FROM schedule_proposals WHERE proposal_id=$rejectId")->fetch_assoc()['status'];p7($rejected==='rejected','parishioner rejection is preserved');
 $expiredId=$service->proposeSchedule($reservationId,['start_at'=>'2097-01-13 14:00:00','service_duration_minutes'=>90,'resource_ids'=>[$resource1]],$owner,'Expiring alternative','2020-01-01 00:00:00');$proposalIds[]=$expiredId;$expired=false;try{$service->respondToProposal($expiredId,$owner,true);}catch(DomainException$e){$expired=true;}p7($expired,'expired proposal cannot be accepted');
 $dueId=(int)$conn->query("SELECT notification_id FROM reservation_notifications WHERE reservation_id=$reservationId AND sent_at IS NULL LIMIT 1")->fetch_assoc()['notification_id'];$conn->query("UPDATE reservation_notifications SET scheduled_for=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE notification_id=$dueId");$runner=new ReservationReminderService($conn);$first=$runner->sendDue();$second=$runner->sendDue();p7($first['sent']===1&&$second['sent']===0,'repeated scheduler execution does not duplicate a reminder');
