}catch(Throwable$e){echo'FAIL: unexpected proposal/reminder error: '.$e->getMessage()."\n";$fail++;}
finally{
 if($blockerId){$conn->query("DELETE FROM reservation_resources WHERE reservation_id=$blockerId");$conn->query("DELETE FROM reservations WHERE reservation_id=$blockerId");}
 if($reservationId){$proposalList=$proposalIds?implode(',',array_map('intval',$proposalIds)):'0';$conn->query("DELETE FROM notifications WHERE notification_id>$notificationFloor AND user_id IN ($owner,$other)");$conn->query("DELETE FROM audit_log WHERE log_id>$auditFloor AND ((table_name='reservations' AND record_id=$reservationId) OR (table_name='schedule_proposals' AND record_id IN ($proposalList)))");$conn->query("DELETE FROM schedule_events WHERE source_type='reservation' AND source_id=$reservationId");$conn->query("DELETE FROM reservation_notifications WHERE reservation_id=$reservationId");$conn->query("DELETE FROM schedule_proposal_resources WHERE proposal_id IN (SELECT proposal_id FROM schedule_proposals WHERE reservation_id=$reservationId)");$conn->query("DELETE FROM schedule_proposals WHERE reservation_id=$reservationId");$conn->query("DELETE FROM reservation_schedule_history WHERE reservation_id=$reservationId");$conn->query("DELETE FROM reservation_resources WHERE reservation_id=$reservationId");$conn->query("DELETE FROM reservations WHERE reservation_id=$reservationId");}
 if($requestId){$conn->query("DELETE FROM request_status_history WHERE request_id=$requestId");$conn->query("DELETE FROM request_idempotency_keys WHERE request_id=$requestId");$conn->query("DELETE FROM requests WHERE request_id=$requestId");}
}
echo"Phase 7 proposal/reminders: $pass passed, $fail failed.\n";exit($fail?1:0);
